<script>
  // Interactive micro-behaviors for Household Kanban
  document.addEventListener('DOMContentLoaded', () => {
    // Quick search filter interaction
    const searchInput = document.getElementById('kanbanSearch');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        const query = e.target.value.toLowerCase().trim();
        const cards = document.querySelectorAll('.group.bg-surface');
        cards.forEach(card => {
          const text = card.textContent.toLowerCase();
          card.style.display = text.includes(query) ? '' : 'none';
        });
      });
    }

    // Interactive Complete toggling
    const completeButtons = document.querySelectorAll('button[title="Mark Done"], button .material-symbols-outlined');
    completeButtons.forEach(btn => {
      const parent = btn.closest('button');
      if (parent && parent.innerText.includes('check')) {
        parent.addEventListener('click', (e) => {
          e.stopPropagation();
          const card = parent.closest('.group');
          if (card) {
            card.classList.toggle('opacity-50');
            card.classList.toggle('scale-95');
          }
        });
      }
    });

    // Quick need input enter listener
    const quickInput = document.getElementById('quickNeedInput');
    if (quickInput) {
      quickInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && quickInput.value.trim() !== '') {
          const itemText = quickInput.value;
          quickInput.value = '';
          quickInput.placeholder = `Added "${itemText}" &bull; Synced!`;
          setTimeout(() => {
            quickInput.placeholder = "Type: '2x Oat Milk from Whole Foods'...";
          }, 3000);
        }
      });
    }
  });
</script></main></div></body></html>